from itertools import combinations, permutations

def to_minutes(s):
    # s like '9:00AM' or '4:15PM'
    s = s.strip().upper()
    am = s.endswith('AM')
    pm = s.endswith('PM')
    s = s[:-2]
    hour, minute = map(int, s.split(':'))
    if am:
        if hour == 12:
            hour = 0
    elif pm:
        if hour != 12:
            hour += 12
    return hour * 60 + minute

def fmt_time(m):
    hour = (m // 60) % 24
    minute = m % 60
    period = 'AM' if hour < 12 else 'PM'
    h12 = hour % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{minute:02d}{period}"

# Directed travel times (minutes)
travel = {
    'Sunset District': {
        'North Beach': 29,
        'Union Square': 30,
        'Alamo Square': 17,
    },
    'North Beach': {
        'Sunset District': 27,
        'Union Square': 7,
        'Alamo Square': 16,
    },
    'Union Square': {
        'Sunset District': 26,
        'North Beach': 10,
        'Alamo Square': 15,
    },
    'Alamo Square': {
        'Sunset District': 16,
        'North Beach': 15,
        'Union Square': 14,
    }
}

# Friends and constraints
friends = [
    {
        'name': 'Sarah',
        'location': 'North Beach',
        'start': to_minutes('4:00PM'),
        'end': to_minutes('6:15PM'),
        'min_duration': 60
    },
    {
        'name': 'Jeffrey',
        'location': 'Union Square',
        'start': to_minutes('3:00PM'),
        'end': to_minutes('10:00PM'),
        'min_duration': 75
    },
    {
        'name': 'Brian',
        'location': 'Alamo Square',
        'start': to_minutes('4:00PM'),
        'end': to_minutes('5:30PM'),
        'min_duration': 75
    }
]

start_location = 'Sunset District'
start_time = to_minutes('9:00AM')

def try_order(order, start_loc, start_t):
    lines = []
    current_loc = start_loc
    t = start_t
    total_travel = 0
    total_meet = 0

    # First line: starting point
    if not lines:
        lines.append(f"You start at {start_loc} at {fmt_time(start_t)}.")

    for fr in order:
        loc = fr['location']
        # Travel
        if current_loc == loc:
            travel_time = 0
        else:
            if current_loc not in travel or loc not in travel[current_loc]:
                return None  # no edge
            travel_time = travel[current_loc][loc]
            t_arrive = t + travel_time
            total_travel += travel_time
            lines.append(f"You travel to {loc} in {travel_time} minutes and arrive at {fmt_time(t_arrive)}.")
            t = t_arrive
            current_loc = loc

        # Wait if early
        earliest_start = max(t, fr['start'])
        latest_start = fr['end'] - fr['min_duration']

        if t > latest_start:
            return None  # infeasible
        if t < earliest_start:
            lines.append(f"You wait until {fmt_time(earliest_start)}.")
        meet_start = earliest_start
        meet_end = meet_start + fr['min_duration']
        if meet_end > fr['end']:
            return None  # infeasible

        lines.append(f"You meet {fr['name']} for {fr['min_duration']} minutes from {fmt_time(meet_start)} to {fmt_time(meet_end)}.")
        total_meet += fr['min_duration']
        t = meet_end

    return {
        'lines': lines,
        'count': len(order),
        'total_meet': total_meet,
        'total_travel': total_travel,
        'end_time': t
    }

best = None
best_key = None

# Enumerate subsets by descending size, and permutations
for r in range(len(friends), 0, -1):
    found_any = False
    for subset in combinations(friends, r):
        for order in permutations(subset):
            res = try_order(order, start_location, start_time)
            if res is None:
                continue
            found_any = True
            # Score: maximize count, then total_meet, then minimize travel, then minimize end time
            key = (res['count'], res['total_meet'], -res['total_travel'], -res['end_time'])
            if best is None or key > best_key:
                best = res
                best_key = key
    if found_any:
        break  # we have the maximum number of friends met

# Output schedule lines
if best is None:
    schedule = [f"You start at {start_location} at {fmt_time(start_time)}.", "No feasible meetings given the constraints."]
else:
    schedule = best['lines']

print(schedule)

