from itertools import permutations, combinations

# Time helpers
BASE_HOUR = 9  # Start at 9:00AM => minutes are offset from 9:00
def minutes_to_time_str(m):
    hour24 = BASE_HOUR + m // 60
    minute = m % 60
    period = "AM" if hour24 < 12 else "PM"
    hour12 = hour24 % 12
    if hour12 == 0:
        hour12 = 12
    return f"{hour12}:{minute:02d}{period}"

# Travel times (directed, in minutes)
travel = {
    "Richmond District": {
        "Sunset District": 11,
        "Haight-Ashbury": 10,
        "Mission District": 20,
        "Golden Gate Park": 9,
    },
    "Sunset District": {
        "Richmond District": 12,
        "Haight-Ashbury": 15,
        "Mission District": 24,
        "Golden Gate Park": 11,
    },
    "Haight-Ashbury": {
        "Richmond District": 10,
        "Sunset District": 15,
        "Mission District": 11,
        "Golden Gate Park": 7,
    },
    "Mission District": {
        "Richmond District": 20,
        "Sunset District": 24,
        "Haight-Ashbury": 12,
        "Golden Gate Park": 17,
    },
    "Golden Gate Park": {
        "Richmond District": 7,
        "Sunset District": 10,
        "Haight-Ashbury": 7,
        "Mission District": 17,
    },
}

# Friend data: location, (window_start, window_end), duration
# Times are minutes after 9:00AM
friends = {
    "Sarah": {
        "location": "Sunset District",
        "window": (105, 600),   # 10:45AM to 7:00PM
        "duration": 30,
    },
    "Richard": {
        "location": "Haight-Ashbury",
        "window": (165, 405),   # 11:45AM to 3:45PM
        "duration": 90,
    },
    "Elizabeth": {
        "location": "Mission District",
        "window": (120, 495),   # 11:00AM to 5:15PM
        "duration": 120,
    },
    "Michelle": {
        "location": "Golden Gate Park",
        "window": (555, 705),   # 6:15PM to 8:45PM
        "duration": 90,
    },
}

start_location = "Richmond District"
start_time = 0  # minutes after 9:00AM

def build_schedule(order):
    """Build a schedule for a given order of friends.
       Returns (steps, total_wait, finish_time, total_travel) if feasible, else None.
    """
    steps = []
    steps.append(f"You start at {start_location} at {minutes_to_time_str(start_time)}.")
    time = start_time
    loc = start_location
    total_wait = 0
    total_travel = 0

    for name in order:
        info = friends[name]
        dest = info["location"]
        win_start, win_end = info["window"]
        duration = info["duration"]

        # Travel
        if loc == dest:
            t_travel = 0
        else:
            if loc not in travel or dest not in travel[loc]:
                return None  # missing edge
            t_travel = travel[loc][dest]
        arr_time = time + t_travel

        # Feasibility check before committing steps:
        earliest_start = max(arr_time, win_start)
        latest_start = win_end - duration
        if earliest_start > latest_start:
            return None  # cannot fit

        # Commit travel step
        if t_travel > 0:
            steps.append(
                f"You travel to {dest} in {t_travel} minutes and arrive at {minutes_to_time_str(arr_time)}."
            )
            total_travel += t_travel
        else:
            steps.append(
                f"You are already at {dest} and the time is {minutes_to_time_str(arr_time)}."
            )

        # Wait if early
        if arr_time < win_start:
            steps.append(f"You wait until {minutes_to_time_str(win_start)}.")
            total_wait += (win_start - arr_time)
            start_meet = win_start
        else:
            start_meet = arr_time

        end_meet = start_meet + duration
        # Meeting step
        steps.append(
            f"You meet {name} for {duration} minutes from {minutes_to_time_str(start_meet)} to {minutes_to_time_str(end_meet)}."
        )

        # Update state
        time = end_meet
        loc = dest

    return steps, total_wait, time, total_travel

# Search best plan:
best = None  # tuple: (num_met, total_wait, finish_time, total_travel, steps)
names = list(friends.keys())

found = False
for k in range(len(names), 0, -1):
    best_k = None
    for subset in combinations(names, k):
        for order in permutations(subset):
            res = build_schedule(order)
            if res is None:
                continue
            steps, wait_time, finish_time, travel_time = res
            score = (k, -wait_time, -finish_time, -travel_time)  # maximize k, then minimize wait, finish, travel
            if best_k is None:
                best_k = (score, steps)
            else:
                if score > best_k[0]:
                    best_k = (score, steps)
    if best_k is not None:
        best = best_k
        break

# Output
if best is None:
    plan = ["No feasible schedule found."]
else:
    plan = best[1]

# Print or return the plan list
print(plan)

